import React from 'react'
import axios from 'axios';
import { useParams, useNavigate } from 'react-router';
import { useState, useEffect } from 'react';



function UpdateProfile() {
    const { id } = useParams();
    const {formData, setFormData} = useState({
        fullname: '',
        email: '',
        password: '',
        phone: ''
    });

    const navigate = useNavigate();

    useEffect(() => {
        const fetchData = async () => {
            try {
                const response = await axios.get(`http://localhost:8080/user/${id}`);
                const itemData = response.data;
                setFormData({
                    fullname: itemData.fullname || '',
                    email: itemData.email || '',
                    password: itemData.password || '',
                    phone: itemData.phone || ''
                });
            } catch (error) {
                console.error("Error fetching user data:", error);
            }
        };

        fetchData();
    },[id])

    const onInputChange = (e) => {
        const { name, value } = e.target;
        setFormData({
            ...formData,
            [name]: value
        });
    }

    const onSubmit = async (e) => {
        e.preventDefault();
        try{
            const response = await axios.put(`http://localhost:8080/user/${id}`, formData);
            alert('Profile update successfully')
            window.location.href = '/userprofile'
        }catch(error){
            alert('Error updating profile:', error);
        }
    }

  return (
    <div>
      <h1>Update Profile</h1>
      <form onSubmit={onSubmit}>

        <label htmlFor="fullname">fullname</label><br />
        <input type="text" id="fullname" name="fullname" onChange={onInputChange} value={formData.fullname} required />
        <br />

        <label htmlFor="email">email</label><br />
        <input type="email" id="email" name="email" value={formData.email} onChange={onInputChange} required /><br />

        <label htmlFor="password">password</label><br />
        <input type="password" id="password" name="password" value={formData.password} onChange={onInputChange} required /><br />

        <label htmlFor="phone">phone</label><br />
        <input type="text" id="phone" name="phone" value={formData.phone} onChange={onInputChange} />
        <br />
        <button type="submit" className="fom_btn">Update Profile</button>
      </form>
    </div>
  )
}

export default UpdateProfile
